-- Links to in-page anchors that don't exist in the document become plain text
-- (typst refuses to build a PDF with dangling labels).
local ids = {}
local function collect(el)
  if el.identifier and el.identifier ~= '' then ids[el.identifier] = true end
end

function Pandoc(doc)
  doc:walk({ Header = collect, Div = collect, Span = collect, Code = collect, CodeBlock = collect, Image = collect, Link = collect, Table = collect, Figure = collect })
  -- footnote and heading ids are generated by pandoc itself; only explicit '#' links to absent ids are removed
  return doc:walk({
    Link = function(l)
      local t = l.target
      if t:sub(1, 1) == '#' and not ids[t:sub(2)] then return l.content end
    end,
  })
end
